export const sortPublications = (items = publications) =>
  [...items].sort((a, b) => {
    const dateA = a.publishedAt ? new Date(`${a.publishedAt}T12:00:00`).getTime() : 0;
    const dateB = b.publishedAt ? new Date(`${b.publishedAt}T12:00:00`).getTime() : 0;
    if (dateA !== dateB) return dateB - dateA;
    return (b.sortOrder ?? 0) - (a.sortOrder ?? 0);
  });

export const reports = sortPublications(
  publications.filter((item) => item.type === "report")
);

